  "tool": "api_fetch",
  "arguments": {
    "method": "POST",
    "url": "/summaries",
    "body": {
      "status": "routed",
      "summary": "event onboarding; route to handler-welcome on queue-orange",
      "toolsCalled": ["api_fetch"]
    }
  }
}

